  "People ask for access from the place they were refused. Granting adds a role to them; declining needs a reason they will read.": "ユーザーは拒否された画面からアクセスを申請します。許可するとロールが追加されます。却下には本人が読む理由が必要です。",
  "The requests": "申請",
