  "Request purge": "削除を申請",
  "Keep my data": "データを残す",
  "Purge requested": "削除を申請しました",
  "It can run after {executes_after}.": "{executes_after} 以降に実行できます。",
  "Purge all data now": "すべてのデータを今すぐ削除",
