  "OpenID Connect": "OpenID Connect",
  "Use your identity provider, such as Microsoft Entra ID or Okta. People who sign in for the first time get the Viewer role and no access grants; give them access under Users.": "Microsoft Entra ID や Okta などの ID プロバイダーを使います。初めてサインインしたユーザーには閲覧者ロールが付与され、アクセス権は付与されません。アクセスは「ユーザー」で付与してください。",
