  "example.com, example.org": "example.com, example.org",
  "Require single sign-on": "シングルサインオンを必須にする",
  "Password sign-in stops for everyone except administrators, who keep it as a way in if the provider is down.": "管理者を除き、パスワードでのサインインは停止します。管理者はプロバイダーの障害時の入口として引き続き使えます。",
