  "Save is waiting for the fields marked above.": "上で示した項目が入力されると保存できます。",
  "Password sign-in": "パスワードでのサインイン",
  "These rules are fixed and apply to every password account. They are not settings.": "これらのルールは固定で、すべてのパスワードアカウントに適用されます。設定項目ではありません。",
  "Password rules": "パスワードのルール",
  "At least 12 characters, not the email name, and not a common password": "12 文字以上、メールの名前ではなく、よく使われるパスワードでもないこと",
  "Lockout": "ロックアウト",
  "10 failed sign-ins lock the account for 15 minutes": "サインインに 10 回失敗すると、アカウントは 15 分間ロックされます",
  "Password sign-in will stop for everyone except administrators. People who cannot sign in through the identity provider will be locked out until an administrator changes this.": "管理者を除き、パスワードでのサインインは停止します。ID プロバイダーでサインインできないユーザーは、管理者が変更するまで締め出されます。",
  "Keep password sign-in": "パスワードでのサインインを維持",
  "The settings are removed. People who signed in through the identity provider keep their accounts and sign in with a password; those who never set one use Forgot password.": "設定は削除されます。ID プロバイダー経由でサインインしていたユーザーはアカウントを保持し、パスワードでサインインします。パスワードを設定していないユーザーは「パスワードをお忘れですか」を使います。",
