  "The licence is not valid. Meridian HQ reports status \"{status}\". Renew it in Meridian HQ; module entitlements may be restricted until then.": "ライセンスが無効です。Meridian HQ の状態は「{status}」です。Meridian HQ で更新してください。それまではモジュールの利用が制限される場合があります。",
  "This deployment has not checked its licence with Meridian HQ, so default entitlements apply: no module list, seat count or expiry. It also checks on a schedule.": "このデプロイメントはまだ Meridian HQ でライセンスを確認していないため、既定の利用権が適用されます（モジュール一覧、シート数、有効期限なし）。定期的な確認も行われます。",
  "The licence has expired. Renew it in Meridian HQ.": "ライセンスの有効期限が切れています。Meridian HQ で更新してください。",
  "The licence expires in {days} {days, plural, one {day} other {days}}. Renew it in Meridian HQ before then; a renewal shows here after the next check.": "ライセンスはあと {days} 日で期限切れになります。それまでに Meridian HQ で更新してください。更新内容は次回の確認後にここに表示されます。",
