  "{filename}{sum}. Load it into SAP with the Migration Cockpit, then confirm the load on the batch.": "{filename}{sum}。Migration Cockpit で SAP に取り込み、その後バッチで取り込みを確認してください。",
  "Exported the load file of batch {label} as {filename}": "バッチ {label} のロードファイルを {filename} としてエクスポートしました",
