  "; severity weights critical {critical}, high {high}, medium {medium}, low {low}; tolerance {value}% of rows or {rows} rows, as set on each rule; cap rule: {cap_rule}.": "。重大度の重み：重大 {critical}、高 {high}、中 {medium}、低 {low}。許容範囲：行の {value}% または {rows} 行（ルールごとの設定）。上限ルール：{cap_rule}。",
