  "The fields are those read by the failing rules of this object in the latest run. Terms are drafted from the rule library with Add terms from the rule library, and a data owner approves each.": "最新の実行でこのオブジェクトの不合格ルールが読み取ったフィールドです。用語は「ルールライブラリから用語を追加」でルールライブラリから下書きされ、データオーナーが 1 件ずつ承認します。",
