  "No survivorship rule is set for this object, so a merge keeps the survivor's value for every field. Add one with Edit the rules.": "このオブジェクトには存続ルールが設定されていないため、マージではすべてのフィールドで存続レコードの値が残ります。「ルールを編集」で追加してください。",
