  "The golden records of {label} could not be read.": "{label} のゴールデンレコードを読み込めませんでした。",
  "No golden records for {label} yet. A match run groups the records that describe the same thing, scores each pair, and a steward approves the survivor; the golden records and the pairs to review land here.": "{label} のゴールデンレコードはまだありません。マッチ実行で同じものを表すレコードをグループ化し、各ペアをスコアリングし、スチュワードが存続レコードを承認します。ゴールデンレコードとレビュー待ちのペアはここに表示されます。",
