  "{source_count} sources": "ソース {source_count} 件",
  "{pending_issues} open {pending_issues, plural, one {conflict} other {conflicts}}": "未解決の競合 {pending_issues} 件",
  "No golden record yet for {label}. The pairs above become golden records when a steward merges them.": "{label} のゴールデンレコードはまだありません。上のペアはスチュワードがマージするとゴールデンレコードになります。",
  "{from} to {to} of {total}": "{total} 件中 {from}〜{to} 件",
  "Confidence is the match engine's score for the surviving record. Last merged is when the record last changed. Open conflicts are fields where the sources disagree and no rule has settled it.": "信頼度は、存続レコードに対するマッチエンジンのスコアです。最終マージはレコードが最後に変更された日時です。未解決の競合は、ソース間で値が異なり、ルールで決着していないフィールドです。",
  "Ledger": "台帳",
  "The ledger of failing records for {label} could not be loaded here. Work lists every record and failing field, ranked by value at risk, with the current value, the suggested value and the decision on the row.": "{label} の不合格レコードの台帳をここに読み込めませんでした。作業画面では、すべてのレコードと不合格フィールドをリスク金額順に、現在の値、提案値、行ごとの判断とともに一覧できます。",
  "The lineage was saved as an SVG file.": "リネージを SVG ファイルとして保存しました。",
  "This browser cannot save the file.": "このブラウザーではファイルを保存できません。",
  "Lineage graph, scrollable": "リネージグラフ（スクロール可能）",
  "Lineage of {label}: {counts} tables, {counts2} fields, {counts3} rules, {counts4} S/4 features": "{label} のリネージ: テーブル {counts}、フィールド {counts2}、ルール {counts3}、S/4 機能 {counts4}",
  "Drawn from the {shown} failing {shown, plural, one {rule} other {rules}} of {label} with the highest value at risk{value}. Features come from the impact model of the current run.": "{label} の不合格ルールのうち、リスク金額の高い {shown} 件から描画しています{value}。機能は現在の実行の影響モデルから取得しています。",
  "; {hidden} more are not drawn": "。ほか {hidden} 件は描画していません",
  "Facts of the node": "ノードの情報",
  "Node facts": "ノードの情報",
  "Open the feature": "機能を開く",
  "Hover or focus a node to see its facts here. Click a rule or a feature to open it.": "ノードにカーソルを合わせるかフォーカスすると、ここに情報が表示されます。ルールや機能をクリックすると開きます。",
  "Export as SVG": "SVG としてエクスポート",
  "The lineage of {label} could not be read.": "{label} のリネージを読み込めませんでした。",
