  "Capped at {cap} by {rule} and {rule2}, two critical rules over tolerance.": "{rule} と {rule2} により {cap} に上限設定されています（許容範囲を超えた重大ルール 2 件）。",
  "Capped at {cap} by {n} critical rules over tolerance, among them {rule} and {rule2}.": "許容範囲を超えた重大ルール {n} 件（{rule}、{rule2} など）により {cap} に上限設定されています。",
  "Held at {cap} by {rule}, one critical rule over tolerance. Measured {measured}, shown {score}.": "{rule} により {cap} に抑えられています（許容範囲を超えた重大ルール 1 件）。測定値 {measured}、表示値 {score}。",
  "Held at {cap} by {rule} and {rule2}, two critical rules over tolerance. Measured {measured}, shown {score}.": "{rule} と {rule2} により {cap} に抑えられています（許容範囲を超えた重大ルール 2 件）。測定値 {measured}、表示値 {score}。",
  "Held at {cap} by {n} critical rules over tolerance, among them {rule} and {rule2}. Measured {measured}, shown {score}.": "許容範囲を超えた重大ルール {n} 件（{rule}、{rule2} など）により {cap} に抑えられています。測定値 {measured}、表示値 {score}。",
