  "this wave": "このウェーブ",
  "A certificate fixes the score of each object of the wave at its latest run, with the exceptions and contracts behind it, and a SHA-256 of that content. A new version replaces nothing: every version stays.": "証明書は、ウェーブの各オブジェクトの最新実行時のスコアを、その背後の例外とコントラクト、およびその内容の SHA-256 とともに記録します。新しいバージョンは何も置き換えず、すべてのバージョンが残ります。",
