  "Drift alerts are turned off for this tenant, so new changes are not compared. An administrator turns them on under Webhooks, Automation.": "このテナントではドリフトのアラートがオフのため、新しい変更は比較されません。管理者が Webhook の自動化で有効にできます。",
  "The configuration changes could not be read.": "構成の変更を読み込めませんでした。",
