  "{changes}. {rules} {rules, plural, one {rule depends} other {rules depend}} on it; {owners} {owners, plural, one {owner} other {owners}} told; {rescore}.": "{changes}。{rules} 件のルールが依存し、{owners} 名のオーナーに通知、{rescore}。",
