  "{monthly} a month in opportunity cost from {blocked} blocked {blocked, plural, one {feature} other {features}}; {since} since each was first blocked.": "ブロックされた {blocked} 件の機能による機会費用は月 {monthly}、それぞれが最初にブロックされてから {since}。",
