  "Rescored from the stored findings of the run of {when}, with the scoring the run used; feature impact from the impact rules.": "{when} の実行の保存済み検出結果から、その実行と同じスコアリングで再計算し、機能への影響は影響ルールから求めています。",
  "Rescored from the stored findings of this object's run, with the scoring the run used; feature impact from the impact rules.": "このオブジェクトの実行の保存済み検出結果から、その実行と同じスコアリングで再計算し、機能への影響は影響ルールから求めています。",
