  "Signed events to Slack, Teams or any https endpoint, the delivery log, and what runs by itself.": "Slack、Teams、任意の https エンドポイントへの署名付きイベント、配信ログ、自動で実行される処理。",
  "{list} and {last}": "{list}、{last}",
