  "{count} data contract {count, plural, one {threshold} other {thresholds}} breached, {enforced} enforced: a baseline cannot be pinned": "データコントラクトのしきい値 {count} 件に違反、適用中 {enforced} 件: 基準を固定できません",
  "{count} data contract {count, plural, one {threshold} other {thresholds}} breached, not enforced": "データコントラクトのしきい値 {count} 件に違反、適用なし",
