  "Could not set password. The invite may have expired. Ask your administrator for a new one.": "パスワードを設定できませんでした。招待の期限が切れている可能性があります。管理者に新しい招待を依頼してください。",
  "Enter the email you sign in with": "サインインに使うメールアドレスを入力してください",
  "We will email a link that works for one hour.": "1 時間有効なリンクをメールでお送りします。",
