  "{name} applied": "{name} を適用しました",
  "{n} {n, plural, one {class} other {classes}} now count as policy breaches when one of their critical rules fails.": "{n} 件のクラスが、重大ルールのいずれかが失敗するとポリシー違反として数えられるようになりました。",
  "Remove the pack": "パックを削除",
  "Apply the pack": "パックを適用",
  "Its classes stop counting as policy breaches on the landscape and the receipt. The rules keep running; you can apply the pack again at any time.": "このパックのクラスは、ランドスケープとレシートでポリシー違反として数えられなくなります。ルールは引き続き実行され、いつでも再適用できます。",
  "Policy packs": "ポリシーパック",
  "Reading policy packs": "ポリシーパックの閲覧",
  "{applied} of {n} packs applied. An applied pack's classes count as policy breaches on the landscape and the receipt when one of their critical rules fails. Authorities are cited by article or section.": "{n} 個中 {applied} 個のパックを適用中。適用中のパックのクラスは、重大ルールのいずれかが失敗するとランドスケープとレシートでポリシー違反として数えられます。規定は条または節で示します。",
  "GxP, SOX and GDPR field classes, the authority each answers to, and the rules that evidence them.": "GxP、SOX、GDPR の項目クラス、それぞれの根拠となる規定、それを裏付けるルール。",
  "The policy packs": "ポリシーパック",
  "No policy pack ships with this version.": "このバージョンにはポリシーパックが含まれていません。",
  "{count} policy {count, plural, one {class} other {classes}} breached: a critical rule evidencing an applied policy pack fails": "{count} 件のポリシークラスで違反: 適用中のポリシーパックの根拠となる重大ルールが失敗しています",
  "Open the classes and evidence": "クラスと根拠を開く",
