  "A copy of the latest run to decide on, to rehearse or to train people, with nothing leaving the deployment: notifications, webhooks, digests, report mailouts and SAP write-backs are held back and logged.": "最新の実行のコピーで判断、リハーサル、トレーニングを行えます。この環境から外へは何も出ません。通知、Webhook、ダイジェスト、レポート送信、SAP への書き戻しは保留され、記録されます。",
  "The sandbox state": "サンドボックスの状態",
