  "Runs copied": "コピーされた実行",
  "Deliveries held back": "保留された配信",
  "Exit sandbox mode": "サンドボックスモードを終了",
  "Enter sandbox mode": "サンドボックスモードを開始",
  "Entering and exiting sandbox mode needs the manage system permission.": "サンドボックスモードの開始と終了には、システム管理の権限が必要です。",
  "The latest finished run is copied into a sandbox run. Until you exit, decisions land on the copy only and nothing leaves this deployment. Decisions on the real run are refused.": "最新の完了済みの実行がサンドボックスの実行にコピーされます。終了するまで判断はコピーにだけ記録され、この環境から外へは何も出ません。本番の実行への判断は拒否されます。",
