  "no rows": "行なし",
  "No finished run to copy: the flag alone is on.": "コピーできる完了済みの実行はありません。フラグのみオンになっています。",
  "The sandbox runs and every decision made on them are discarded. Deliveries held back are not sent afterwards.": "サンドボックスの実行とそこでの判断はすべて破棄されます。保留された配信は後から送信されません。",
  "Discard the sandbox and exit": "サンドボックスを破棄して終了",
