  "As of run": "実行時点",
  "The fix sheet reads today's rows without a policy or a past run; clear them to export": "修正シートはポリシーや過去の実行を使わず現在の行を読み込みます。エクスポートするにはそれらを解除してください",
  "As it stood at run {when}; statuses are today's.": "{when} の実行時点の状態です。ステータスは現在のものです。",
  "Each object is read at its newest run up to then. Counts on the chips are today's.": "各オブジェクトはその時点までの最新の実行で読み込まれます。チップの件数は現在のものです。",
  "The history of this record could not be read.": "このレコードの履歴を読み込めませんでした。",
  "No run has measured this record yet, and nothing has been decided on it.": "このレコードを測定した実行はまだなく、判断も行われていません。",
  "Every run": "すべての実行",
  "{n} {n, plural, one {run} other {runs}} measured this record, {failing} with it failing. Values are as each run stored them; the work status is today's.": "{n} 回の実行がこのレコードを測定し、そのうち {failing} 回で失敗していました。値は各実行が保存したもので、作業ステータスは現在のものです。",
  "Runs of this record, scrollable": "このレコードの実行（スクロール可能）",
