  "Since {when}.": "{when} から。",
  "Decisions land on the sandbox copy; notifications, webhooks, digests and write-backs are held back.": "判断はサンドボックスのコピーに記録されます。通知、Webhook、ダイジェスト、書き戻しは保留されます。",
  "Sandbox settings": "サンドボックスの設定",
  "Start with ? to ask in a sentence, such as ?critical vendors assigned to me due this week. The answer is a ledger filter you can see before it runs.": "? で始めると文章で質問できます（例: ?critical vendors assigned to me due this week）。回答は台帳のフィルターで、実行前に内容を確認できます。",
  "Ask in a sentence": "文章で質問",
  "Type a question after the ?, such as ?vendor bank data in ECC production, or ?overdue materials assigned to me.": "? の後に質問を入力してください（例: ?vendor bank data in ECC production、?overdue materials assigned to me）。",
  "The filter that will run": "実行されるフィルター",
  "The question could not be read. Try other words, or search without the ?.": "質問を読み込めませんでした。別の言葉を試すか、? を付けずに検索してください。",
