  "{band}, {confidence}": "{band}、{confidence}",
  "Cost": "コスト",
  "{amount} ({low} to {high})": "{amount}（{low} から {high}）",
  "The cost model prices no run: set the run cost per hour or per million records under Settings": "コストモデルに実行の単価がありません。設定で 1 時間あたり、または 100 万レコードあたりの実行コストを設定してください",
