  "{who} was refused ({status_code}): {asked}": "{who} は拒否されました（{status_code}）: {asked}",
  "Three steps to your first scores": "最初のスコアまでの 3 つのステップ",
  "Connect a system or upload a file": "システムを接続するか、ファイルをアップロード",
  "Connect an SAP system (ECC, S/4HANA, SuccessFactors, Ariba, Concur or BTP) and extract it, or upload one object as CSV, Excel or Parquet. Nothing leaves your environment.": "SAP システム（ECC、S/4HANA、SuccessFactors、Ariba、Concur、BTP）を接続して抽出するか、1 つのオブジェクトを CSV、Excel、Parquet でアップロードします。データが環境の外に出ることはありません。",
  "Connecting a system needs the manage systems permission. Ask an administrator to grant it.": "システムの接続には「システムの管理」権限が必要です。管理者に付与を依頼してください。",
  "Run an analysis": "分析を実行",
  "Every rule of every object is checked against the extracted records. Before it starts you see how long it should take; the job line under the top bar shows its progress.": "各オブジェクトのすべてのルールが、抽出されたレコードに対してチェックされます。開始前に所要時間の目安が表示され、上部バーの下のジョブラインに進捗が表示されます。",
  "Running an analysis needs the analyse permission. Ask an administrator to grant it.": "分析の実行には「分析」権限が必要です。管理者に付与を依頼してください。",
  "Read the landscape": "ランドスケープを読む",
  "Each object gets a score on the ruler, a verdict and the records to fix. This page then opens with the one sentence that says what holds the landscape back, and your next step.": "各オブジェクトにルーラー上のスコア、判定、修正すべきレコードが付きます。このページは、ランドスケープを妨げている要因を示す一文と、次のステップから始まるようになります。",
