  "Administration: {section}": "管理: {section}",
  "Demo data": "デモデータ",
  "Every figure on this page is sample data built into the interface, not read from your SAP systems.": "このページの数値はすべてインターフェースに組み込まれたサンプルデータであり、お使いの SAP システムから読み取ったものではありません。",
  "{measured} measured": "計測 {measured}",
  "Object not found": "オブジェクトが見つかりません",
  "{system} has no object called {segment}. Open the landscape and choose an object from the map.": "{system} に {segment} というオブジェクトはありません。ランドスケープを開き、マップからオブジェクトを選んでください。",
  "Record not found": "レコードが見つかりません",
  "No failing record with the key {key} is in the latest run. Check the key; a record fixed since the list was read also leaves it.": "最新の実行に、キー {key} の不合格レコードはありません。キーを確認してください。一覧を読み込んだ後に修正されたレコードも一覧から外れます。",
  "Completeness (short)": "完",
  "Accuracy (short)": "正",
  "Consistency (short)": "貫",
  "Timeliness (short)": "時",
  "Uniqueness (short)": "一",
  "Validity (short)": "妥",
