  "No failed job is waiting. A job that fails and is not followed by a success of the same kind lands here.": "待機中の失敗ジョブはありません。失敗した後に同じ種類の成功が続かないジョブがここに表示されます。",
  "{JOB_KIND_LABEL} of {jobObject}": "{jobObject} の{JOB_KIND_LABEL}",
  "Authorisation errors": "権限エラー",
