  "SAP could not be checked.": "SAP を確認できませんでした。",
  "The batch was not sent to SAP": "バッチは SAP に送信されませんでした",
  "Sending to SAP needs the approve permission, which your role does not hold.": "SAP への送信には承認権限が必要ですが、あなたのロールにはありません。",
  "Check with SAP first.": "先に SAP で確認してください。",
  "No field of this batch goes by BAPI; deliver it with the load file.": "このバッチには BAPI で送信できる項目がありません。ロードファイルで引き渡してください。",
  "Live write-back": "SAP への直接書き戻し",
  "This deployment writes approved values to SAP through its BAPIs. Check with SAP first: it says which fields a BAPI carries and why the others go out with the load file. Nothing is sent by the check.": "このデプロイメントは、承認済みの値を SAP の BAPI で書き戻します。まず SAP で確認してください。どの項目を BAPI で送信でき、他の項目がなぜロードファイルで引き渡されるかが表示されます。確認では何も送信されません。",
  "Checking with SAP needs the apply permission, which your role does not hold.": "SAP での確認には適用権限が必要ですが、あなたのロールにはありません。",
  "Check with SAP": "SAP で確認",
  "Fields by BAPI": "BAPI で送信する項目",
  "Fields by export": "エクスポートで送る項目",
  "Fields checked with SAP": "SAP で確認した項目",
  "Sent {sent}, failed {failed}, export only {exportOnly}.": "送信 {sent} 件、失敗 {failed} 件、エクスポートのみ {exportOnly} 件。",
  "The fields without a BAPI were not sent; deliver them with the load file.": "BAPI のない項目は送信されていません。ロードファイルで引き渡してください。",
  "What SAP answered, per record": "レコードごとの SAP の応答",
  "{records} {n, plural, one {record is} other {records are}} written to SAP now. Each is checked in a test run first, and SAP commits only a record whose answer holds no error. A committed change cannot be taken back from here.": "{records} 件のレコードを今すぐ SAP に書き込みます。各レコードはまずテスト実行で確認され、応答にエラーがないレコードだけが SAP で確定されます。確定した変更はここから取り消せません。",
  "Send {records} {n, plural, one {record} other {records}}": "{records} 件のレコードを送信",
  "Export batch {label} as a load file": "バッチ {label} をロードファイルとしてエクスポート",
  "Export load file": "ロードファイルをエクスポート",
  "Written to SAP": "SAP に書き込み済み",
  "Records sent": "送信したレコード",
  "Records failed": "失敗したレコード",
  "Fields for export only": "エクスポートのみの項目",
  "Read through": "読み取り経路",
  "ODP, table reader for the rest": "ODP、残りはテーブルリーダー",
