  "Cloud systems are read through their APIs": "クラウドシステムは API で読み取ります",
  "No extraction job with table detail is on record": "テーブル詳細のある抽出ジョブの記録がありません",
  "Automatic: table reader": "自動: テーブルリーダー",
  "OData through the SAP Gateway": "SAP Gateway 経由の OData",
  "Reads each table with the table reader below. Needs read access to the tables.": "下のテーブルリーダーで各テーブルを読み取ります。テーブルへの読み取り権限が必要です。",
  "Reads mapped tables through ODP providers (RODPS_REPL). Fields a provider does not carry are reported per table; other tables use the table reader.": "マッピングされたテーブルを ODP プロバイダー（RODPS_REPL）で読み取ります。プロバイダーにない項目はテーブルごとに報告し、その他のテーブルはテーブルリーダーを使います。",
  "Reads with the table reader. ODP is used only when you choose it, after confirming with SAP that your licence allows it (SAP Note 3255746).": "テーブルリーダーで読み取ります。ODP は、ライセンスで許可されていることを SAP に確認したうえで選択した場合にのみ使用します（SAP Note 3255746）。",
  "Reads through the released APIs your Gateway exposes, such as API_PRODUCT_SRV and API_BUSINESS_PARTNER, with this system's user.": "Gateway が公開するリリース済み API（API_PRODUCT_SRV、API_BUSINESS_PARTNER など）を、このシステムのユーザーで読み取ります。",
  "Deployment default": "デプロイの既定値",
  "Find the first available": "最初に使えるものを探す",
  "The function that reads tables the extraction path does not cover. Agree it with your Basis team.": "抽出経路で扱わないテーブルを読み取る汎用モジュールです。Basis チームと合意してください。",
  "Gateway base URL": "Gateway ベース URL",
  "The SAP Gateway of this system, for example https://s4host:44300. Meridian sends this system's client as sap-client.": "このシステムの SAP Gateway（例: https://s4host:44300）。Meridian はこのシステムのクライアントを sap-client として送信します。",
